insert into public.categories (name)
select c.name from (values ($q$Kenyan Food & Culture$q$), ($q$Kenyan Wildlife & Culture$q$), ($q$Matatus & Transport$q$), ($q$Music & Entertainment$q$), ($q$Safaricom & Tech$q$), ($q$Swahili & Sheng$q$)) as c(name)
where not exists (select 1 from public.categories x where x.name = c.name);

insert into public.questions
