  ($q$Kenyan Wildlife & Culture$q$, $q$How many bones are in a giraffe's neck?$q$, $q$Three$q$, $q$Twelve$q$, $q$Seven$q$, $q$Twenty$q$, 'c', 'hard', $q$That is the same number as in a human neck, but each giraffe bone is very long.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$About how long is an elephant pregnant?$q$, $q$9 months$q$, $q$12 months$q$, $q$36 months$q$, $q$22 months$q$, 'd', 'hard', $q$That is the longest pregnancy of any land animal.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which big cat can purr but cannot roar?$q$, $q$The cheetah$q$, $q$The lion$q$, $q$The leopard$q$, $q$The tiger$q$, 'a', 'medium', $q$Cheetahs chirp, purr and growl, but they do not roar.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$About how many wildebeest take part in the Great Migration?$q$, $q$About 15,000$q$, $q$About 150,000$q$, $q$About 1.5 million$q$, $q$About 15 million$q$, 'c', 'hard', $q$Hundreds of thousands of zebras and gazelles travel with them.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$Which agency manages Kenya's national parks and reserves?$q$, $q$The Kenya Forest Service$q$, $q$Kenya Railways$q$, $q$The National Museums of Kenya$q$, $q$The Kenya Wildlife Service$q$, 'd', 'medium', $q$It is often called KWS for short.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$In which year was the Kenya Wildlife Service established?$q$, $q$1989$q$, $q$1963$q$, $q$1977$q$, $q$2003$q$, 'a', 'hard', $q$Richard Leakey was its first director.$q$),
  ($q$Kenyan Wildlife & Culture$q$, $q$In which year did Mount Kenya National Park join the UNESCO World Heritage List?$q$, $q$1987$q$, $q$1997$q$, $q$2001$q$, $q$2011$q$, 'b', 'hard', $q$Lake Turkana National Parks were added in the same year.$q$),
